// SW03 · intrare pentru gardă
// Numărul de amânări e limitat, ca un mesaj amânat repetat să nu circule la nesfârșit.
// Generat de scripts/build-n8n.mjs — nu edita în n8n, modifică sursa.

const input = $('Când primește cererea').first().json;
const config = $input.first().json.config;

return [{ json: {
  client_id: config.client.id,
  contact: input.contact,
  request: input.request,
  now: input.now,
  template: input.template,
  defer_count: input.defer_count || 0,
} }];

// SW03 · limită de amânări
// Trei amânări înseamnă că mesajul nu mai e relevant; se renunță și se loghează, nu se reia la infinit.
// Generat de scripts/build-n8n.mjs — nu edita în n8n, modifică sursa.

const decision = $input.first().json;
const prepared = $('Pregătește garda').first().json;
const attempts = (prepared.defer_count || 0) + 1;
const MAX_DEFERS = 3;

return [{ json: {
  ...prepared,
  defer_count: attempts,
  decision,
  give_up: attempts > MAX_DEFERS,
  resume_at: decision.defer_until,
} }];

// SW03 · reluare după amânare
// Se reintră în gardă cu contorul de amânări păstrat.
// Generat de scripts/build-n8n.mjs — nu edita în n8n, modifică sursa.

const item = $input.first().json;
return [{ json: {
  client_id: item.client_id,
  contact: item.contact,
  request: item.request,
  template: item.template,
  defer_count: item.defer_count,
  now: new Date().toISOString(),
} }];

// SW03 · randare
// Merge fields și fallback-uri. Un mesaj cu o valoare financiară lipsă nu pleacă.
// Generat de scripts/build-n8n.mjs — nu edita în n8n, modifică sursa.

/**
 * Randarea template-urilor și regula de fallback pentru merge fields.
 *
 * Regula nenegociabilă: un email cu «Bună, {{prenume}}» gol nu pleacă niciodată.
 * Fiecare token are o strategie declarată în config.merge_fields:
 *   value          → se înlocuiește cu o valoare implicită
 *   alternate_line → rândul care îl conține se schimbă complet
 *   omit_sentence  → propoziția care îl conține dispare
 *   block_send     → mesajul nu pleacă și se ridică alertă
 *
 * Valorile financiare și calendaristice (avans, sold, termen, dată plecare) sunt
 * toate block_send prin config: mai bine un mesaj netrimis decât un mesaj cu un
 * sold gol.
 */

const TOKEN_RE = /\{\{\s*([\w.]+)\s*\}\}/g;

function resolveSource(source, { contact, config }) {
  const fields = contact.customFields || {};
  if (source.startsWith('custom_field.')) return fields[source.slice('custom_field.'.length)];
  if (source.startsWith('contact.')) return contact[source.slice('contact.'.length)];
  if (source.startsWith('config.')) {
    return source.slice('config.'.length).split('.').reduce((acc, k) => (acc == null ? undefined : acc[k]), config);
  }
  return undefined;
}

const isEmpty = (v) => v === undefined || v === null || String(v).trim() === '';

// Intl introduce spații insecabile (U+00A0, U+202F) în sume și date. Arată la
// fel, dar strică potrivirile de text și numărătoarea de segmente SMS.
const despace = (s) => String(s).replace(/[\u00A0\u202F]/g, ' ');

function formatValue(value, format, config) {
  if (isEmpty(value)) return '';
  if (format === 'currency') {
    const n = Number(String(value).replace(/[^\d.,-]/g, '').replace(',', '.'));
    if (!Number.isFinite(n)) return String(value);
    return despace(new Intl.NumberFormat(config.client.locale, { style: 'currency', currency: config.client.currency, maximumFractionDigits: 0 }).format(n));
  }
  if (format && /y{2,4}/.test(format)) {
    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return String(value);
    return despace(new Intl.DateTimeFormat(config.client.locale, { day: 'numeric', month: 'long', year: 'numeric', timeZone: config.client.timezone }).format(d));
  }
  return String(value);
}

/** Elimină propoziția care conține un token, păstrând restul paragrafului. */
function omitSentenceContaining(text, token) {
  const marker = new RegExp(`\\{\\{\\s*${token}\\s*\\}\\}`);
  return text
    .split('\n')
    .map((line) => {
      if (!marker.test(line)) return line;
      const sentences = line.split(/(?<=[.!?])\s+/);
      return sentences.filter((s) => !marker.test(s)).join(' ').trim();
    })
    .filter((line, i, arr) => line !== '' || arr[i - 1] === '')
    .join('\n');
}

/**
 * @param {object} args
 * @param {object} args.config
 * @param {object} args.contact  { customFields, firstName, … }
 * @param {object} args.template { subject?, body, channel }
 * @returns {{ok:boolean, subject:string, body:string, blocked:string[], substituted:object, warnings:string[]}}
 */
function renderTemplate({ config, contact, template }) {
  const byToken = new Map(config.merge_fields.map((mf) => [mf.token, mf]));
  const blocked = [];
  const warnings = [];
  const substituted = {};

  let subject = template.subject || '';
  let body = template.body || '';

  const used = new Set();
  for (const text of [subject, body]) {
    for (const match of text.matchAll(TOKEN_RE)) used.add(match[1]);
  }

  for (const token of used) {
    const mf = byToken.get(token);
    if (!mf) {
      // Un token nedeclarat înseamnă template greșit, nu date lipsă: mai bine
      // oprim trimiterea decât să livrăm „{{ceva}}" clientului.
      blocked.push(token);
      warnings.push(`token "${token}" nu e declarat în config.merge_fields`);
      continue;
    }

    const raw = resolveSource(mf.source, { contact, config });
    const value = formatValue(raw, mf.format, config);
    substituted[token] = value;

    if (!isEmpty(value)) continue;

    switch (mf.fallback_strategy) {
      case 'value':
        substituted[token] = mf.fallback_value;
        break;
      case 'alternate_line': {
        // Rândul care conține tokenul se înlocuiește integral, ca să nu rămână „Bună, !"
        const marker = new RegExp(`\\{\\{\\s*${token}\\s*\\}\\}`);
        const swap = (text) => text.split('\n').map((l) => (marker.test(l) ? mf.alternate_line : l)).join('\n');
        subject = swap(subject);
        body = swap(body);
        substituted[token] = mf.fallback_value ?? '';
        break;
      }
      case 'omit_sentence':
        subject = omitSentenceContaining(subject, token);
        body = omitSentenceContaining(body, token);
        substituted[token] = '';
        break;
      case 'block_send':
      default:
        blocked.push(token);
        break;
    }
  }

  if (blocked.length) {
    return { ok: false, subject, body, blocked, substituted, warnings };
  }

  const replace = (text) => text.replace(TOKEN_RE, (whole, token) => (token in substituted ? substituted[token] : whole));
  subject = replace(subject);
  body = replace(body);

  // Ce a mai rămas neînlocuit e o scăpare de template, nu o valoare lipsă.
  const leftovers = [...`${subject}\n${body}`.matchAll(TOKEN_RE)].map((m) => m[1]);
  if (leftovers.length) {
    return { ok: false, subject, body, blocked: [...new Set(leftovers)], substituted, warnings: [...warnings, 'tokens nerezolvate după randare'] };
  }

  if (template.channel === 'sms') {
    const limit = config.content.sms_limits.max_chars_gsm7;
    if (body.length > limit) {
      return { ok: false, subject, body, blocked: [], substituted, warnings: [...warnings, `SMS de ${body.length} caractere, peste limita de ${limit}`] };
    }
    if (config.content.sms_limits.warn_chars && body.length > config.content.sms_limits.warn_chars) {
      warnings.push(`SMS de ${body.length} caractere — mai mult de un segment`);
    }
  }

  return { ok: true, subject, body, blocked: [], substituted, warnings };
}

// ── glue n8n ──
const decision = $input.first().json;
const prepared = $('Pregătește garda').first().json;
const config = $('Încarcă configul').first().json.config;

const rendered = renderTemplate({
  config,
  contact: prepared.contact,
  template: { ...prepared.template, channel: prepared.request.channel },
});

return [{ json: {
  ...prepared,
  decision,
  rendered,
  can_send: rendered.ok,
} }];

// SW03 · payload GHL
// Email și SMS pleacă prin canalul nativ GHL; sub-contul e sursa de adevăr pentru conversații.
// Generat de scripts/build-n8n.mjs — nu edita în n8n, modifică sursa.

const item = $input.first().json;
const config = $('Încarcă configul').first().json.config;
const channel = item.request.channel;

const body = {
  type: channel === 'sms' ? 'SMS' : 'Email',
  contactId: item.contact.id,
  message: item.rendered.body,
};
if (channel === 'email') {
  body.subject = item.rendered.subject;
  body.html = item.rendered.body.replace(/\n/g, '<br>');
  body.emailFrom = config.integrations.email.from_name + ' <' + config.integrations.email.from_address + '>';
  if (config.integrations.email.reply_to) body.emailReplyTo = config.integrations.email.reply_to;
}

return [{ json: {
  client_id: item.client_id,
  method: 'POST',
  path: '/conversations/messages',
  body,
  _context: item,
} }];

// SW03 · jurnal de trimiteri
// Jurnalul de pe contact este ce face idempotența și plafonul de frecvență să funcționeze.
// Generat de scripts/build-n8n.mjs — nu edita în n8n, modifică sursa.

/**
 * Garda de trimitere — singurul loc în care se decide dacă un mesaj pleacă.
 *
 * Rulează identic în Node (pentru teste) și într-un node Code din n8n: scriptul
 * de build îl inlinează în workflow, deci logica testată aici este exact logica
 * din producție.
 *
 * Funcție pură: primește configul, contactul și cererea; nu face I/O. Toate
 * datele de contact vin de la apelant (SW01 · GHL API), ca să poată fi testată
 * pe scenarii fără să atingă GHL.
 *
 * Ordinea verificărilor contează: conformitatea are prioritate absolută, apoi
 * idempotența (ieftină, previne dublurile), apoi regulile de business.
 */

/** Părțile datei în fusul orar dat, fără dependințe. */
function zonedParts(date, timeZone) {
  const fmt = new Intl.DateTimeFormat('en-US', {
    timeZone, hour12: false,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
  });
  const parts = {};
  for (const p of fmt.formatToParts(date)) if (p.type !== 'literal') parts[p.type] = Number(p.value);
  if (parts.hour === 24) parts.hour = 0;
  return parts;
}

/** Decalajul fusului față de UTC, în minute, la momentul dat. */
function offsetMinutes(date, timeZone) {
  const p = zonedParts(date, timeZone);
  const asUtc = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second);
  return (asUtc - Math.floor(date.getTime() / 1000) * 1000) / 60000;
}

/**
 * Instantul UTC pentru o oră locală dintr-o zi locală dată.
 * Două treceri, ca să prindem corect zilele de schimbare a orei.
 */
function utcFromLocal(year, month, day, hour, minute, timeZone) {
  let guess = new Date(Date.UTC(year, month - 1, day, hour, minute));
  for (let i = 0; i < 2; i++) {
    const off = offsetMinutes(guess, timeZone);
    guess = new Date(Date.UTC(year, month - 1, day, hour, minute) - off * 60000);
  }
  return guess;
}

/** Următorul moment în care canalul are voie să trimită. null = acum e în regulă. */
function nextAllowedWindow(now, timeZone, window) {
  if (!window || !window.enforced) return null;
  const [startH, startM] = window.start.split(':').map(Number);
  const [endH, endM] = window.end.split(':').map(Number);
  const p = zonedParts(now, timeZone);
  const minutesNow = p.hour * 60 + p.minute;
  const startMin = startH * 60 + startM;
  const endMin = endH * 60 + endM;

  if (minutesNow >= startMin && minutesNow < endMin) return null;

  if (minutesNow < startMin) return utcFromLocal(p.year, p.month, p.day, startH, startM, timeZone);
  // După fereastră: prima fereastră de mâine.
  const tomorrow = new Date(utcFromLocal(p.year, p.month, p.day, 12, 0, timeZone).getTime() + 24 * 3600 * 1000);
  const tp = zonedParts(tomorrow, timeZone);
  return utcFromLocal(tp.year, tp.month, tp.day, startH, startM, timeZone);
}

function parseJournal(raw) {
  if (!raw) return [];
  try {
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    // Un jurnal corupt nu are voie să blocheze trimiterile tranzacționale, dar
    // nici să deschidă porțile la spam: se tratează ca jurnal gol și se
    // raportează, ca să fie vizibil în alertare.
    return [];
  }
}

function buildIdempotencyKey(template, values) {
  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => String(values[key] ?? ''));
}

function pruneJournal(journal, now, retentionDays) {
  const cutoff = now.getTime() - retentionDays * 86400000;
  return journal.filter((e) => {
    const t = Date.parse(e.t);
    return Number.isFinite(t) && t >= cutoff;
  });
}

/**
 * @param {object} args
 * @param {object} args.config   configul clientului
 * @param {object} args.contact  { id, tags: string[], customFields: Record<string,any> }
 * @param {object} args.request  { flow_id, step_id, channel, category, kind, occurrence_key }
 * @param {string} [args.nowIso]
 * @returns {{action:'send'|'defer'|'drop', allowed:boolean, reason:string, defer_until:string|null,
 *            idempotency_key:string, journal_kept:number, detail?:object}}
 */
function evaluateGuard({ config, contact, request, nowIso }) {
  const now = nowIso ? new Date(nowIso) : new Date();
  const rules = config.sending_rules;
  const timeZone = config.client.timezone;
  const tags = (contact.tags || []).map((t) => String(t).toLowerCase());
  const fields = contact.customFields || {};

  const idempotencyKey = buildIdempotencyKey(rules.idempotency.key_template, {
    client_id: config.client.id,
    contact_id: contact.id,
    flow_id: request.flow_id,
    step_id: request.step_id,
    occurrence_key: request.occurrence_key ?? '',
  });

  const journal = pruneJournal(parseJournal(fields[rules.log.field_key]), now, rules.log.retention_days);
  const deny = (action, reason, detail) => ({
    action, allowed: false, reason, detail,
    defer_until: detail?.defer_until ?? null,
    idempotency_key: idempotencyKey,
    journal_kept: journal.length,
  });

  const isCommercial = request.kind === 'commercial';

  // 1. Canalul trebuie să fie efectiv disponibil. WhatsApp fără BSP aprobat nu
  //    e o eroare de rulare, e un pas care încă nu poate exista.
  if (request.channel === 'whatsapp' && !config.integrations.whatsapp.enabled) {
    return deny('drop', 'channel_unavailable', { channel: 'whatsapp' });
  }

  // 2. Conformitate: opt-out bate orice flux, inclusiv tranzacțional comercial.
  const optoutTag = (config.compliance.optout_tags || {})[request.channel];
  if (optoutTag && tags.includes(optoutTag.toLowerCase())) {
    return deny('drop', 'opted_out', { tag: optoutTag });
  }

  // 3. Consimțământ pe canalul respectiv. Fără el nu se trimite, indiferent de flux.
  if (config.compliance.consent_required_per_channel) {
    const consent = (config.compliance.consent_fields || {})[request.channel];
    const value = consent ? fields[consent.flag] : undefined;
    const granted = value === true || value === 'true' || value === 1 || value === '1' || value === 'yes';
    if (!granted) return deny('drop', 'no_consent', { field: consent?.flag, value: value ?? null });
  }

  // 4. Idempotență: re-rularea unui workflow nu retrimite același mesaj.
  if (journal.some((e) => e.key === idempotencyKey)) {
    return deny('drop', 'duplicate', { idempotency_key: idempotencyKey });
  }

  // 5. Suprimare între fluxuri: cine e în plecare / în vacanță / la întoarcere
  //    nu primește Early Booking, Last Minute sau nurturing.
  if (isCommercial) {
    const flowPrefix = config.taxonomy.system_tag_prefixes.flow_state;
    const blocking = rules.suppression.exclusive_flow_ids
      .map((flowId) => `${flowPrefix}${flowId}`.toLowerCase())
      .filter((tag) => tags.includes(tag));
    if (blocking.length) return deny('drop', 'suppressed_by_exclusive_flow', { tags: blocking });
  }

  // 6. Plafonul de frecvență. Tranzacționalele trec peste el prin definiție.
  if (isCommercial || !rules.frequency_cap.transactional_bypasses_cap) {
    const cap = rules.frequency_cap.commercial;
    const windowStart = now.getTime() - cap.rolling_days * 86400000;
    const recent = journal
      .filter((e) => e.k === 'commercial' && Date.parse(e.t) >= windowStart)
      .sort((a, b) => Date.parse(a.t) - Date.parse(b.t));

    if (recent.length >= cap.max_messages) {
      // Se amână până iese cel mai vechi mesaj din fereastra rulantă, nu se pierde.
      const oldest = Date.parse(recent[0].t);
      const freeAt = new Date(oldest + cap.rolling_days * 86400000);
      return deny('defer', 'frequency_cap', {
        defer_until: freeAt.toISOString(),
        sent_in_window: recent.length,
        max: cap.max_messages,
      });
    }

    const minGapHours = rules.frequency_cap.min_hours_between_commercial || 0;
    if (minGapHours > 0 && recent.length) {
      const last = Date.parse(recent[recent.length - 1].t);
      const nextOk = last + minGapHours * 3600000;
      if (now.getTime() < nextOk) {
        return deny('defer', 'min_gap_between_commercial', {
          defer_until: new Date(nextOk).toISOString(),
          min_hours: minGapHours,
        });
      }
    }
  }

  // 7. Ferestre orare. Se aplică pe canal, în fusul clientului.
  const window = rules.quiet_hours.per_channel[request.channel];
  const nextWindow = nextAllowedWindow(now, timeZone, window);
  if (nextWindow) {
    if (rules.quiet_hours.defer_strategy === 'drop') {
      return deny('drop', 'outside_sending_window', { window });
    }
    return deny('defer', 'outside_sending_window', { defer_until: nextWindow.toISOString(), window });
  }

  return {
    action: 'send',
    allowed: true,
    reason: 'ok',
    defer_until: null,
    idempotency_key: idempotencyKey,
    journal_kept: journal.length,
  };
}

/** Intrarea de adăugat în jurnal după o trimitere reușită. */
function journalEntry({ request, idempotencyKey, nowIso }) {
  return {
    t: nowIso || new Date().toISOString(),
    f: request.flow_id,
    s: request.step_id,
    c: request.channel,
    k: request.kind,
    cat: request.category,
    key: idempotencyKey,
  };
}

// ── glue n8n ──
const sendResult = $input.first().json;
const item = $('Construiește mesajul GHL').first().json._context;
const config = $('Încarcă configul').first().json.config;
const rules = config.sending_rules;
const nowIso = new Date().toISOString();

const journal = pruneJournal(
  parseJournal(item.contact.customFields?.[rules.log.field_key]),
  new Date(nowIso),
  rules.log.retention_days,
);
journal.push(journalEntry({
  request: item.request,
  idempotencyKey: item.decision.idempotency_key,
  nowIso,
}));

const commercialInWindow = journal.filter((e) =>
  e.k === 'commercial' && Date.parse(e.t) >= Date.now() - rules.frequency_cap.commercial.rolling_days * 86400000
).length;

const human = rules.log.human_readable_fields || {};
const customFields = [{ key: rules.log.field_key, field_value: JSON.stringify(journal) }];
if (human.count_rolling) customFields.push({ key: human.count_rolling, field_value: commercialInWindow });
if (human.last_commercial && item.request.kind === 'commercial') {
  customFields.push({ key: human.last_commercial, field_value: nowIso });
}

return [{ json: {
  client_id: item.client_id,
  method: 'PUT',
  path: '/contacts/' + item.contact.id,
  // Forma exactă a customFields la update diferă între conturi GHL
  // ({key, field_value} vs {id, value}); se confirmă la primul test end-to-end
  // pe sub-contul real — vezi docs/05, scenariul T0.4.
  body: { customFields },
  _log: {
    client_id: item.client_id,
    contact_id: item.contact.id,
    flow_id: item.request.flow_id,
    step_id: item.request.step_id,
    channel: item.request.channel,
    category: item.request.category,
    kind: item.request.kind,
    status: 'sent',
    reason: 'ok',
    idempotency_key: item.decision.idempotency_key,
    timestamp: nowIso,
    provider_response: JSON.stringify(sendResult.data ?? {}).slice(0, 500),
  },
} }];

// SW03 · linie de log
// Fiecare trimitere se loghează cu contact, flux, canal, timestamp și status.
// Generat de scripts/build-n8n.mjs — nu edita în n8n, modifică sursa.

return [{ json: $('Actualizează jurnalul').first().json._log }];

// SW03 · linie de log pentru mesaj oprit
// Un mesaj suprimat e la fel de important de urmărit ca unul trimis.
// Generat de scripts/build-n8n.mjs — nu edita în n8n, modifică sursa.

const decision = $input.first().json.decision || $input.first().json;
const prepared = $('Pregătește garda').first().json;
return [{ json: {
  client_id: prepared.client_id,
  contact_id: prepared.contact.id,
  flow_id: prepared.request.flow_id,
  step_id: prepared.request.step_id,
  channel: prepared.request.channel,
  category: prepared.request.category,
  kind: prepared.request.kind,
  status: decision.action === 'defer' ? 'given_up_after_defers' : 'blocked',
  reason: decision.reason,
  idempotency_key: decision.idempotency_key,
  timestamp: new Date().toISOString(),
  detail: JSON.stringify(decision.detail ?? {}),
} }];

// SW03 · linie de log pentru randare blocată
// Merge field lipsă = mesaj netrimis + alertă, nu email cu spații goale.
// Generat de scripts/build-n8n.mjs — nu edita în n8n, modifică sursa.

const item = $input.first().json;
return [{ json: {
  client_id: item.client_id,
  contact_id: item.contact.id,
  flow_id: item.request.flow_id,
  step_id: item.request.step_id,
  channel: item.request.channel,
  category: item.request.category,
  kind: item.request.kind,
  status: 'blocked',
  reason: 'merge_fields_lipsa',
  idempotency_key: item.decision.idempotency_key,
  timestamp: new Date().toISOString(),
  detail: JSON.stringify({ blocked: item.rendered.blocked, warnings: item.rendered.warnings }),
} }];
